function f = HS35_f(x)
f = 2*x(1).^2 + 2*x(1).*x(2) + 2*x(1).*x(3) - 8*x(1) + 2*x(2).^2 - 6*x(2) + x(3).^2 - 4*x(3) + 9;
end

